package com.projexa.coaching.examinations.controller;
import com.projexa.coaching.common.tenant.TenantContextHolder; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/questions") public class QuestionBankController {private final JdbcTemplate db;public QuestionBankController(JdbcTemplate db){this.db=db;}
@GetMapping @PreAuthorize("hasAnyAuthority('questions.manage','exams.manage')") public List<Map<String,Object>> list(@RequestParam(required=false) UUID subjectId,@RequestParam(required=false) String type){UUID t=TenantContextHolder.getRequired();if(subjectId!=null&&type!=null)return db.queryForList("select * from questions where tenant_id=? and subject_id=? and question_type=? and active=true order by created_at desc",t,subjectId,type);if(subjectId!=null)return db.queryForList("select * from questions where tenant_id=? and subject_id=? and active=true order by created_at desc",t,subjectId);return db.queryForList("select * from questions where tenant_id=? and active=true order by created_at desc",t);}
@PostMapping @PreAuthorize("hasAuthority('questions.manage')") public Map<String,Object> create(@RequestBody Question q){UUID t=TenantContextHolder.getRequired(),id=UUID.randomUUID();db.update("insert into questions(id,tenant_id,subject_id,text,question_type,difficulty,topic,chapter,marks,active) values(?,?,?,?,?,?,?,?,?,true)",id,t,q.subjectId(),q.text(),q.questionType(),q.difficulty(),q.topic(),q.chapter(),q.marks());if(q.options()!=null)for(int i=0;i<q.options().size();i++){Option o=q.options().get(i);db.update("insert into question_options(id,question_id,option_text,is_correct,display_order) values(?,?,?,?,?)",UUID.randomUUID(),id,o.text(),o.correct(),i);}return Map.of("id",id);}
public record Question(UUID subjectId,String text,String questionType,String difficulty,String topic,String chapter,double marks,List<Option> options){} public record Option(String text,boolean correct){}
}
